const crypto = require('crypto');

const FIELD_MAPPINGS = {
  sales_sheet: {
    department: 'sales',
    fields: {
      status:            { keys: ['Status', 'status'],                     type: 'string', required: true },
      amount:            { keys: ['deal_amount'],                     type: 'number', required: true },
      lead_source:       { keys: ['Lead Source', 'lead_source'],           type: 'string', required: false },
      marketing_spend:   { keys: ['Marketing Spend', 'marketing_spend'],   type: 'number', required: false },
      created_date:      { keys: ['Created Date', 'created_date', 'date'],         type: 'date',   required: true },
    }
  },
  project_delivery_base: {
    department: 'project_delivery',
    fields: {
      status:            { keys: ['Status', 'status'],                     type: 'string', required: true },
      project_name: { keys: ['project_name', 'Project_name'],
                    type: 'string', required: true},
      project_id: { keys: ['project_id', 'Project_id'],
                    type: 'string', required: true},
      owner: { keys: ['owner', 'Owner'],
                    type: 'string', required: true},
      kickoff_date: { keys: ['kickoff_date', 'Kickoff_date'], type: 'date', required: true},
      team:              { keys: ['Team', 'team'],                         type: 'string', required: false },
      due_date:          { keys: ['Due Date', 'due_date'],                 type: 'date',   required: true },
      completed_date:    { keys: ['Completed Date', 'completed_date'],     type: 'date',   required: false },
      actual_cost:       { keys: ['Actual Cost', 'actual_cost'],           type: 'number', required: false },
      budgeted_cost:     { keys: ['Budgeted Cost', 'budgeted_cost'],       type: 'number', required: false },
    }
  },
  people_ops_api: {
    department: 'people_ops',
    fields: {
      employee_id:      { keys: ['employee_id'],                       type: 'string', required: true },
      department_name:      { keys: ['department'],                       type: 'string', required: true },
      role:      { keys: ['role', 'Role'],                       type: 'string', required: true },
      application_date:     { keys: ['application_date'],                 type: 'date',   required: true },
      offer_accepted_date:  { keys: ['offer_accepted_date'],               type: 'date',   required: false },
      start_date:           { keys: ['start_date'],                       type: 'date',   required: false },
      exit_date:            { keys: ['exit_date'],                        type: 'date',   required: false },
      employment_status:    { keys: ['status', 'employment_status'],      type: 'string', required: false },
    }
  }
};

function isBlank(v) {
  return v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
}

function isInvalidDate(v) {
  return !isBlank(v) && isNaN(Date.parse(v));
}

// Pulls raw values into the canonical shape using the config's key list
function mapFields(source, raw) {
  const config = FIELD_MAPPINGS[source];
  if (!config) return { data: {}, department: 'unknown' };

  const data = {};
  for (const [canonicalField, meta] of Object.entries(config.fields)) {
    const rawValue = meta.keys.map(k => raw[k]).find(v => v !== undefined);
    data[canonicalField] = rawValue ?? null;
  }
  return { data, department: config.department };
}

// Generic: loops over every field defined in the config, no per-field hardcoding
function getQualityFlags(source, data) {
  const config = FIELD_MAPPINGS[source];
  if (!config) return ['unknown_source'];

  const flags = [];
  for (const [field, meta] of Object.entries(config.fields)) {
    const value = data[field];

    if (isBlank(value) && meta.required) {
      flags.push(`missing_${field}`);
    }
    if (meta.type === 'date' && isInvalidDate(value)) {
      flags.push(`invalid_${field}`);
    }
  }
  return flags;
}

const departmentBySource = {
  sales_sheet: 'sales',
  project_delivery_base: 'project_delivery',
  people_ops_api: 'people_ops',
};

const normalized = items.map((item) => {
  const raw = item.json;
  const source = raw.source;

  const { data } = mapFields(source, raw);
  const quality_flags = getQualityFlags(source, data);

  const record_hash = crypto
    .createHash('sha256')
    .update(JSON.stringify(data))
    .digest('hex');

  const source_record_id =
    raw.source_record_id || raw.id || raw.airtable_record_id ||
    raw.recordId || raw.record_id || raw.employee_id || raw.lead_id || null;

  // Flag missing IDs explicitly — these can't be deduped against future syncs
  if (source_record_id === null) {
    quality_flags.push('missing_source_record_id');
  }

  return {
    json: {
      source,
      department: departmentBySource[source] || 'unknown',
      source_record_id,
      record_hash,
      synced_at: new Date().toISOString(),
      quality_flags,
      data,
    },
  };
});

return normalized;

return items.map((item) => {
  const raw = item.json;

  const flattened = raw.fields ? { ...raw.fields } : { ...raw };

  // Always preserve Airtable's own record id and creation timestamp,
  // even when project_id already exists — you want both available downstream.
  if (raw.id) flattened.airtable_record_id = raw.id;
  if (raw.createdTime) flattened.airtable_created_time = raw.createdTime;

  flattened.source = 'project_delivery_base';

  return { json: flattened };
});

// Cleaning / standardization node
// Runs AFTER the normalize node — receives items already in canonical shape:
// { source, department, source_record_id, record_hash, synced_at, quality_flags, data }

function cleanString(value) {
  if (value === null || value === undefined) return null;
  const trimmed = String(value).trim();
  if (trimmed === '') return null;
  return trimmed;
}

// Standardizes casing for controlled-vocabulary fields (status, department names)
// so "closed won", "Closed Won ", "CLOSED WON" all collapse to one canonical form.
function standardizeEnum(value, mapping) {
  const cleaned = cleanString(value);
  if (cleaned === null) return null;
  const key = cleaned.toLowerCase();
  return mapping[key] || cleaned; // fall back to cleaned original if no mapping matches
}

const STATUS_MAP = {
  'closed won': 'Closed Won',
  'closed lost': 'Closed Lost',
  'qualified': 'Qualified',
  'proposal sent': 'Proposal Sent',
  'in progress': 'In Progress',
  'blocked': 'Blocked',
  'completed': 'Completed',
  'not started': 'Not Started',
};

// Parses a variety of date formats into a strict ISO 8601 date string (YYYY-MM-DD).
// Returns null (not a throw) on anything unparseable — the quality_flags system
// already caught invalid dates upstream; this just avoids silently passing through
// a Date object or inconsistent string format into Supabase.
function toIsoDate(value) {
  if (value === null || value === undefined || value === '') return null;

  const parsed = new Date(value);
  if (isNaN(parsed.getTime())) return null;

  return parsed.toISOString().split('T')[0]; // YYYY-MM-DD, drop time component
}

// Strips currency symbols, commas, and whitespace, then parses to a float.
// Returns null (not NaN) on failure — never let NaN leak downstream into metrics/Claude.
function toCleanNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return isNaN(value) ? null : value;

  const cleaned = String(value).replace(/[$,€£\s]/g, '').trim();
  if (cleaned === '') return null;

  const parsed = parseFloat(cleaned);
  return isNaN(parsed) ? null : parsed;
}

// Declares, per department, which cleaning function applies to which field —
// same config-driven pattern as the normalize node, so adding a department
// later means adding a config entry, not new cleaning logic.
const CLEANING_RULES = {
  sales: {
    status: (v) => standardizeEnum(v, STATUS_MAP),
    amount: toCleanNumber,
    marketing_spend: toCleanNumber,
    lead_source: cleanString,
    created_date: toIsoDate,
    close_date: toIsoDate,
  },
  project_delivery: {
    status: (v) => standardizeEnum(v, STATUS_MAP),
    team: cleanString,
    owner: cleanString,
    project_name: cleanString,
    due_date: toIsoDate,
    completed_date: toIsoDate,
    kickoff_date: toIsoDate,
    actual_cost: toCleanNumber,
    budgeted_cost: toCleanNumber,
  },
  people_ops: {
    department_name: cleanString,
    employment_status: (v) => standardizeEnum(v, STATUS_MAP),
    application_date: toIsoDate,
    offer_accepted_date: toIsoDate,
    start_date: toIsoDate,
    exit_date: toIsoDate,
  },
};

const cleaned = items.map((item) => {
  const record = item.json;
  const rules = CLEANING_RULES[record.department] || {};

  const cleanedData = { ...record.data };
  for (const [field, cleanFn] of Object.entries(rules)) {
    if (field in cleanedData) {
      cleanedData[field] = cleanFn(cleanedData[field]);
    }
  }

  return {
    json: {
      ...record,
      data: cleanedData,
      cleaned_at: new Date().toISOString(),
    },
  };
});

return cleaned;

// Grab the original normalized items from BEFORE the Supabase lookup —
// not from the lookup node's output, so nothing depends on what it returned.
const originalItems = $('is unique_identifier present?').all(); 
// ^ adjust to whatever your split/IF node is actually named

// The bulk lookup results — whatever rows DID exist in Supabase
const existingRecords = items; // output of the "Get Many Rows" node feeding into this Code node

// Build a lookup map: source_record_id -> existing row's stored hash
const existingMap = new Map();
for (const row of existingRecords) {
  existingMap.set(row.json.source_record_id, row.json.record_hash);
}

const results = originalItems.map((item) => {
  const record = item.json;
  const existingHash = existingMap.get(record.source_record_id);

  let action;
  if (existingHash === undefined) {
    action = 'insert'; // no match found — brand new record
  } else if (existingHash === record.record_hash) {
    action = 'duplicate'; // same ID, same hash — true duplicate, skip
  } else {
    action = 'update'; // same ID, different hash — something changed
  }

  return {
    json: {
      ...record,
      action,
    },
  };
});

return results;

const records = items
  .map(item => ({
    source: item.json.source,
    department: item.json.department,
    source_record_id: item.json.source_record_id,
    record_hash: item.json.record_hash,
    quality_flags: item.json.quality_flags,
    data: item.json.data,
    synced_at: item.json.synced_at,
  }));

return [{ json: { records } }];

const period = $('Loop Over Items').item.json;
const periodStart = new Date(period.start_date);
const periodEnd = new Date(period.end_date);
periodEnd.setHours(23, 59, 59, 999);

//  compute the immediately-preceding period of the same length 
const periodLengthMs = periodEnd.getTime() - periodStart.getTime();
const prevPeriodEnd = new Date(periodStart.getTime() - 1); // 
const prevPeriodStart = new Date(prevPeriodEnd.getTime() - periodLengthMs);

function inRange(dateStr, rangeStart, rangeEnd) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return false;
  return d >= rangeStart && d <= rangeEnd;
}

const allRecords = items.map(i => i.json);
const sales = allRecords.filter(r => r.department === 'sales');
const projects = allRecords.filter(r => r.department === 'project_delivery');
const peopleOps = allRecords.filter(r => r.department === 'people_ops');

// wrap entire existing calculation block in a function
function calculateMetrics(rangeStart, rangeEnd) {
  const inPeriod = (dateStr) => inRange(dateStr, rangeStart, rangeEnd);

  // SALES 
  const salesInPeriod = sales.filter(r => inPeriod(r.data.created_date));
  const closedWon = salesInPeriod.filter(r => r.data.status === 'Closed Won');
  const closedLost = salesInPeriod.filter(r => r.data.status === 'Closed Lost');
  const openDeals = salesInPeriod.filter(r => ['Qualified', 'Proposal Sent'].includes(r.data.status));

  const totalLeads = salesInPeriod.length;
  const revenueWon = closedWon.reduce((sum, r) => sum + (r.data.amount || 0), 0);
  const pipelineValue = openDeals.reduce((sum, r) => sum + (r.data.amount || 0), 0);
  const wonPlusLost = closedWon.length + closedLost.length;
  const winRate = wonPlusLost > 0 ? closedWon.length / wonPlusLost : null;

  const monthlySpendMap = {};
  const monthlySpendConflicts = new Set();
  for (const r of salesInPeriod) {
    const dateStr = r.data.created_date;
    if (!dateStr) continue;
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) continue;
    const monthKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    const spend = r.data.marketing_spend;
    if (spend === null || spend === undefined) continue;
    if (monthKey in monthlySpendMap) {
      if (monthlySpendMap[monthKey] !== spend) monthlySpendConflicts.add(monthKey);
    } else {
      monthlySpendMap[monthKey] = spend;
    }
  }
  const marketingSpend = Object.values(monthlySpendMap).reduce((sum, v) => sum + v, 0);
  const costPerLead = totalLeads > 0 ? marketingSpend / totalLeads : null;

  const revenueByLeadSource = {};
  for (const r of closedWon) {
    const src = r.data.lead_source || 'Unknown';
    revenueByLeadSource[src] = (revenueByLeadSource[src] || 0) + (r.data.amount || 0);
  }

  const salesMetrics = {
    total_leads: totalLeads, closed_won: closedWon.length, closed_lost: closedLost.length,
    pipeline_value: pipelineValue, revenue_won: revenueWon, win_rate: winRate,
    marketing_spend: marketingSpend, cost_per_lead: costPerLead,
    revenue_by_lead_source: revenueByLeadSource,
  };

  //  PROJECT DELIVERY 
const activeProjects = projects.filter(r => {
  const status = r.data.status;
  if (!['In Progress'].includes(status)) return false;

  const kickoff = r.data.kickoff_date ? new Date(r.data.kickoff_date) : null;
  // Project must have actually started by the end of the period —
  // this is the check that was missing entirely before.
  if (!kickoff || kickoff > rangeEnd) return false;

  const completed = r.data.completed_date ? new Date(r.data.completed_date) : null;
  // Still "active during period" if not yet completed, or completed on/after period start
  return !completed || completed >= rangeStart;
});

const completedInPeriod = projects.filter(r => inPeriod(r.data.completed_date));

// Blocked count now scoped to the period, per your business rule:
// a blocked project only counts if it KICKED OFF within the selected range.
const blockedProjects = projects.filter(r =>
  r.data.status === 'Blocked' && inPeriod(r.data.kickoff_date)
);
  const completedWithDueDates = completedInPeriod.filter(r => r.data.due_date && r.data.completed_date);
  const onTimeCompleted = completedWithDueDates.filter(r => new Date(r.data.completed_date) <= new Date(r.data.due_date));
  const onTimeRate = completedWithDueDates.length > 0 ? onTimeCompleted.length / completedWithDueDates.length : null;
  const lateCompleted = completedWithDueDates.filter(r => new Date(r.data.completed_date) > new Date(r.data.due_date));
  const avgDelay = lateCompleted.length > 0
    ? lateCompleted.reduce((sum, r) => sum + (new Date(r.data.completed_date) - new Date(r.data.due_date)) / 86400000, 0) / lateCompleted.length
    : null;
  const projectsWithCosts = completedInPeriod.filter(r => r.data.actual_cost !== null && r.data.budgeted_cost !== null);
  const overBudgetProjects = projectsWithCosts.filter(r => r.data.actual_cost > r.data.budgeted_cost);
  const avgBudgetVariance = projectsWithCosts.length > 0
    ? projectsWithCosts.reduce((sum, r) => sum + (r.data.actual_cost - r.data.budgeted_cost), 0) / projectsWithCosts.length
    : null;
  const deliveryLoadByTeam = {};
  for (const r of [...activeProjects, ...completedInPeriod]) {
    const team = r.data.team || 'Unassigned';
    deliveryLoadByTeam[team] = (deliveryLoadByTeam[team] || 0) + 1;
  }

  const projectMetrics = {
    active_projects: activeProjects.length, completed_projects: completedInPeriod.length,
    blocked_projects: blockedProjects.length, on_time_completion_rate: onTimeRate,
    average_delay_days: avgDelay, over_budget_projects: overBudgetProjects.length,
    average_budget_variance: avgBudgetVariance, delivery_load_by_team: deliveryLoadByTeam,
  };

  // PEOPLE OPS 
  const applications = peopleOps.filter(r => inPeriod(r.data.application_date));
  const offersAccepted = peopleOps.filter(r => inPeriod(r.data.offer_accepted_date));
  const newHires = peopleOps.filter(r => inPeriod(r.data.start_date));
  const exits = peopleOps.filter(r => inPeriod(r.data.exit_date));

  const activeHeadcount = peopleOps.filter(r => {
    const start = r.data.start_date ? new Date(r.data.start_date) : null;
    const exit = r.data.exit_date ? new Date(r.data.exit_date) : null;
    if (!start || start > rangeEnd) return false;
    if (exit && exit <= rangeEnd) return false;
    return true;
  }).length;

  const activeHeadcountAtStart = peopleOps.filter(r => {
    const start = r.data.start_date ? new Date(r.data.start_date) : null;
    const exit = r.data.exit_date ? new Date(r.data.exit_date) : null;
    if (!start || start >= rangeStart) return false;
    if (exit && exit < rangeStart) return false;
    return true;
  }).length;

  const attritionRate = activeHeadcountAtStart > 0 ? exits.length / activeHeadcountAtStart : null;

  const hiresWithBothDates = newHires.filter(r => r.data.application_date && r.data.start_date);
  const timeToHire = hiresWithBothDates.length > 0
    ? hiresWithBothDates.reduce((sum, r) => sum + (new Date(r.data.start_date) - new Date(r.data.application_date)) / 86400000, 0) / hiresWithBothDates.length
    : null;

  const offersWithBothDates = offersAccepted.filter(r => r.data.application_date && r.data.offer_accepted_date);
  const offerAcceptanceTime = offersWithBothDates.length > 0
    ? offersWithBothDates.reduce((sum, r) => sum + (new Date(r.data.offer_accepted_date) - new Date(r.data.application_date)) / 86400000, 0) / offersWithBothDates.length
    : null;

  const headcountByDept = {};
  for (const r of peopleOps) {
    const start = r.data.start_date ? new Date(r.data.start_date) : null;
    const exit = r.data.exit_date ? new Date(r.data.exit_date) : null;
    const isActiveAtEnd = start && start <= rangeEnd && (!exit || exit > rangeEnd);
    if (isActiveAtEnd) {
      const dept = r.data.department || 'Unassigned';
      headcountByDept[dept] = (headcountByDept[dept] || 0) + 1;
    }
  }

  const peopleOpsMetrics = {
    applications: applications.length, offers_accepted: offersAccepted.length,
    new_hires: newHires.length, exits: exits.length, active_headcount: activeHeadcount,
    time_to_hire_days: timeToHire, offer_acceptance_time_days: offerAcceptanceTime,
    attrition_rate: attritionRate, headcount_by_department: headcountByDept,
  };

  return { sales: salesMetrics, project_delivery: projectMetrics, people_ops: peopleOpsMetrics, monthlySpendConflicts };
}

// call it twice 
const currentMetrics = calculateMetrics(periodStart, periodEnd);
const previousMetrics = calculateMetrics(prevPeriodStart, prevPeriodEnd);

//DATA QUALITY SUMMARY
const salesInPeriod = sales.filter(r => inRange(r.data.created_date, periodStart, periodEnd));
const activeProjectsCheck = projects.filter(r => inRange(r.data.completed_date, periodStart, periodEnd) || ['In Progress','Blocked'].includes(r.data.status));
const applicationsCheck = peopleOps.filter(r => inRange(r.data.application_date, periodStart, periodEnd));

const flagCounts = {};
for (const r of allRecords) {
  for (const flag of (r.quality_flags || [])) {
    flagCounts[flag] = (flagCounts[flag] || 0) + 1;
  }
}
const departmentsWithNoRecords = [];
if (currentMetrics.sales.total_leads === 0) departmentsWithNoRecords.push('sales');
if (currentMetrics.project_delivery.active_projects === 0 && currentMetrics.project_delivery.completed_projects === 0) departmentsWithNoRecords.push('project_delivery');
if (currentMetrics.people_ops.applications === 0 && currentMetrics.people_ops.new_hires === 0) departmentsWithNoRecords.push('people_ops');

const dataQualitySummary = {
  flag_counts: {
    ...flagCounts,
    ...(currentMetrics.monthlySpendConflicts.size > 0 ? { inconsistent_marketing_spend_in_month: currentMetrics.monthlySpendConflicts.size } : {})
  },
  total_flagged_records: allRecords.filter(r => (r.quality_flags || []).length > 0).length,
  departments_with_no_records: departmentsWithNoRecords,
};

// FINAL OUTPUT 
return [{
  json: {
    period_type: period.period_type,
    start_date: period.start_date,
    end_date: period.end_date,
    metrics: {
      sales: currentMetrics.sales,
      project_delivery: currentMetrics.project_delivery,
      people_ops: currentMetrics.people_ops,
    },
    previous_period: {
      sales: previousMetrics.sales,
      project_delivery: previousMetrics.project_delivery,
      people_ops: previousMetrics.people_ops,
    },
    data_quality_summary: dataQualitySummary,
  }
}];

// Single source of truth for "today" — see prior note on testing vs production.
const REFERENCE_DATE = '2026-06-30'; // TESTING: matches KPI guide's fixed dataset anchor
// const REFERENCE_DATE = null;      // PRODUCTION: switch to this for real "today"

const now = REFERENCE_DATE ? new Date(REFERENCE_DATE) : new Date();

function toDateStr(d) {
  return d.toISOString().split('T')[0];
}

const periods = [];

// Last 30 days
{
  const start = new Date(now);
  start.setDate(start.getDate() - 30);
  periods.push({ period_type: 'last_30', start_date: toDateStr(start), end_date: toDateStr(now) });
}

// Last 90 days
{
  const start = new Date(now);
  start.setDate(start.getDate() - 90);
  periods.push({ period_type: 'last_90', start_date: toDateStr(start), end_date: toDateStr(now) });
}

// Year to date
{
  const start = new Date(now.getFullYear(), 0, 1);
  periods.push({ period_type: 'ytd', start_date: toDateStr(start), end_date: toDateStr(now) });
}

return periods.map(p => ({ json: p }));

// Runs immediately after the Claude node.
// Claude's response now only contains AI-generated fields (executive_summary,
// risks_or_anomalies, recommended_actions, data_quality_notes).
// period_type, start_date, end_date, metrics, and data_quality_summary are
// pulled directly from the metrics node — Claude never echoes them back.

function extractRawText(item) {
  const json = item.json;

  if (typeof json.content === 'string') return json.content;
  if (Array.isArray(json.content) && json.content[0]?.text) return json.content[0].text;
  if (json.text) return json.text;
  if (json.message?.content?.[0]?.text) return json.message.content[0].text;

  return null;
}

function stripMarkdownFence(text) {
  if (!text) return text;
  return text
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

// Claude's response schema is now just the AI fields
const REQUIRED_KEYS = [
  'executive_summary',
  'risks_or_anomalies',
  'recommended_actions',
  'data_quality_notes',
];

const results = items.map((item) => {
  // Always pull passthrough fields from the original metrics node —
  // needed on BOTH the success and fallback paths.
  // Update 'Calculate Metrics' to your actual metrics node's name.
  const originalInput = $('calculate metrics').item.json;

  const passthrough = {
    period_type: originalInput.period_type ?? null,
    start_date: originalInput.start_date ?? null,
    end_date: originalInput.end_date ?? null,
    metrics: originalInput.metrics ?? null,
    data_quality_summary: originalInput.data_quality_summary ?? null,
    previous_period: originalInput.previous_period ?? null
  };

  const rawText = extractRawText(item);
  const cleanedText = stripMarkdownFence(rawText);

  let aiFields;
  let parseSucceeded = true;

  try {
    if (!cleanedText) throw new Error('No text content found in Claude response');
    const parsed = JSON.parse(cleanedText);

    const hasAllKeys = REQUIRED_KEYS.every(k => k in parsed);
    if (!hasAllKeys) throw new Error('Parsed JSON missing required fields');

    aiFields = {
      executive_summary: parsed.executive_summary,
      risks_or_anomalies: parsed.risks_or_anomalies,
      recommended_actions: parsed.recommended_actions,
      data_quality_notes: parsed.data_quality_notes,
    };

  } catch (err) {
    parseSucceeded = false;
    aiFields = {
      executive_summary: null,
      risks_or_anomalies: [],
      recommended_actions: [],
      data_quality_notes: null,
      parse_error: err.message,
    };
  }

  return {
    json: {
      ...passthrough,
      ...aiFields,
      ai_parse_succeeded: parseSucceeded,
    },
  };
});

return results;

// Runs immediately after the Claude node.
// Claude's response now only contains AI-generated fields (executive_summary,
// risks_or_anomalies, recommended_actions, data_quality_notes).
// period_type, start_date, end_date, metrics, and data_quality_summary are
// pulled directly from the metrics node — Claude never echoes them back.

function extractRawText(item) {
  const json = item.json;

  if (typeof json.content === 'string') return json.content;
  if (Array.isArray(json.content) && json.content[0]?.text) return json.content[0].text;
  if (json.text) return json.text;
  if (json.message?.content?.[0]?.text) return json.message.content[0].text;

  return null;
}

function stripMarkdownFence(text) {
  if (!text) return text;
  return text
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

// Claude's response schema is now just the AI fields
const REQUIRED_KEYS = [
  'executive_summary',
  'risks_or_anomalies',
  'recommended_actions',
  'data_quality_notes',
];

const results = items.map((item) => {
  // Always pull passthrough fields from the original metrics node —
  // needed on BOTH the success and fallback paths.
  // Update 'Calculate Metrics' to your actual metrics node's name.
  const originalInput = $('calculate metrics for custom range').item.json;

  const passthrough = {
    period_type: originalInput.period_type ?? null,
    start_date: originalInput.start_date ?? null,
    end_date: originalInput.end_date ?? null,
    metrics: originalInput.metrics ?? null,
    data_quality_summary: originalInput.data_quality_summary ?? null,
    previous_period: originalInput.previous_period ?? null,
  };

  const rawText = extractRawText(item);
  const cleanedText = stripMarkdownFence(rawText);

  let aiFields;
  let parseSucceeded = true;

  try {
    if (!cleanedText) throw new Error('No text content found in Claude response');
    const parsed = JSON.parse(cleanedText);

    const hasAllKeys = REQUIRED_KEYS.every(k => k in parsed);
    if (!hasAllKeys) throw new Error('Parsed JSON missing required fields');

    aiFields = {
      executive_summary: parsed.executive_summary,
      risks_or_anomalies: parsed.risks_or_anomalies,
      recommended_actions: parsed.recommended_actions,
      data_quality_notes: parsed.data_quality_notes,
    };

  } catch (err) {
    parseSucceeded = false;
    aiFields = {
      executive_summary: null,
      risks_or_anomalies: [],
      recommended_actions: [],
      data_quality_notes: null,
      parse_error: err.message,
    };
  }

  return {
    json: {
      ...passthrough,
      ...aiFields,
      ai_parse_succeeded: parseSucceeded,
    },
  };
});

return results;

const webhookData = $('Webhook').first().json.body;

const period = {
  start_date: webhookData.start_date,
  end_date: webhookData.end_date,
};

const periodStart = new Date(period.start_date);
const periodEnd = new Date(period.end_date);
periodEnd.setHours(23, 59, 59, 999);

// --- Previous period: same length, immediately preceding ---
const periodLengthMs = periodEnd.getTime() - periodStart.getTime();
const prevPeriodEnd = new Date(periodStart.getTime() - 1); // 1ms before current period starts
const prevPeriodStart = new Date(prevPeriodEnd.getTime() - periodLengthMs);

function inRange(dateStr, rangeStart, rangeEnd) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return false;
  return d >= rangeStart && d <= rangeEnd;
}

// All fetched records (every department, unfiltered by date)
const allRecords = items.map(i => i.json);

const sales = allRecords.filter(r => r.department === 'sales');
const projects = allRecords.filter(r => r.department === 'project_delivery');
const peopleOps = allRecords.filter(r => r.department === 'people_ops');

// ============================================
// Reusable calculation — same logic, now parameterized by range
// ============================================
function calculateMetrics(rangeStart, rangeEnd) {
  const inPeriod = (dateStr) => inRange(dateStr, rangeStart, rangeEnd);

  // ===== SALES =====
  const salesInPeriod = sales.filter(r => inPeriod(r.data.created_date));

  const closedWon = salesInPeriod.filter(r => r.data.status === 'Closed Won');
  const closedLost = salesInPeriod.filter(r => r.data.status === 'Closed Lost');
  const openDeals = salesInPeriod.filter(r => ['Qualified', 'Proposal Sent'].includes(r.data.status));

  const totalLeads = salesInPeriod.length;
  const revenueWon = closedWon.reduce((sum, r) => sum + (r.data.amount || 0), 0);
  const pipelineValue = openDeals.reduce((sum, r) => sum + (r.data.amount || 0), 0);

  const wonPlusLost = closedWon.length + closedLost.length;
  const winRate = wonPlusLost > 0 ? closedWon.length / wonPlusLost : null;

  const monthlySpendMap = {};
  const monthlySpendConflicts = new Set();
  for (const r of salesInPeriod) {
    const dateStr = r.data.created_date;
    if (!dateStr) continue;
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) continue;
    const monthKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    const spend = r.data.marketing_spend;
    if (spend === null || spend === undefined) continue;
    if (monthKey in monthlySpendMap) {
      if (monthlySpendMap[monthKey] !== spend) monthlySpendConflicts.add(monthKey);
    } else {
      monthlySpendMap[monthKey] = spend;
    }
  }
  const marketingSpend = Object.values(monthlySpendMap).reduce((sum, v) => sum + v, 0);
  const costPerLead = totalLeads > 0 ? marketingSpend / totalLeads : null;

  const revenueByLeadSource = {};
  for (const r of closedWon) {
    const src = r.data.lead_source || 'Unknown';
    revenueByLeadSource[src] = (revenueByLeadSource[src] || 0) + (r.data.amount || 0);
  }

  const salesMetrics = {
    total_leads: totalLeads,
    closed_won: closedWon.length,
    closed_lost: closedLost.length,
    pipeline_value: pipelineValue,
    revenue_won: revenueWon,
    win_rate: winRate,
    marketing_spend: marketingSpend,
    cost_per_lead: costPerLead,
    revenue_by_lead_source: revenueByLeadSource,
  };

  // ===== PROJECT DELIVERY =====
  const activeProjects = projects.filter(r => {
    const status = r.data.status;
    if (!['In Progress'].includes(status)) return false;

    const kickoff = r.data.kickoff_date ? new Date(r.data.kickoff_date) : null;
    if (!kickoff || kickoff > rangeEnd) return false;

    const completed = r.data.completed_date ? new Date(r.data.completed_date) : null;
    return !completed || completed >= rangeStart;
  });

  const completedInPeriod = projects.filter(r => inPeriod(r.data.completed_date));

  const blockedProjects = projects.filter(r =>
    r.data.status === 'Blocked' && inPeriod(r.data.kickoff_date)
  );

  const completedWithDueDates = completedInPeriod.filter(r => r.data.due_date && r.data.completed_date);
  const onTimeCompleted = completedWithDueDates.filter(r =>
    new Date(r.data.completed_date) <= new Date(r.data.due_date)
  );
  const onTimeRate = completedWithDueDates.length > 0
    ? onTimeCompleted.length / completedWithDueDates.length
    : null;

  const lateCompleted = completedWithDueDates.filter(r =>
    new Date(r.data.completed_date) > new Date(r.data.due_date)
  );
  const avgDelay = lateCompleted.length > 0
    ? lateCompleted.reduce((sum, r) => {
        const diffDays = (new Date(r.data.completed_date) - new Date(r.data.due_date)) / (1000 * 60 * 60 * 24);
        return sum + diffDays;
      }, 0) / lateCompleted.length
    : null;

  const projectsWithCosts = completedInPeriod.filter(r =>
    r.data.actual_cost !== null && r.data.budgeted_cost !== null
  );
  const overBudgetProjects = projectsWithCosts.filter(r => r.data.actual_cost > r.data.budgeted_cost);
  const avgBudgetVariance = projectsWithCosts.length > 0
    ? projectsWithCosts.reduce((sum, r) => sum + (r.data.actual_cost - r.data.budgeted_cost), 0) / projectsWithCosts.length
    : null;

  const deliveryLoadByTeam = {};
  for (const r of [...activeProjects, ...completedInPeriod]) {
    const team = r.data.team || 'Unassigned';
    deliveryLoadByTeam[team] = (deliveryLoadByTeam[team] || 0) + 1;
  }

  const projectMetrics = {
    active_projects: activeProjects.length,
    completed_projects: completedInPeriod.length,
    blocked_projects: blockedProjects.length,
    on_time_completion_rate: onTimeRate,
    average_delay_days: avgDelay,
    over_budget_projects: overBudgetProjects.length,
    average_budget_variance: avgBudgetVariance,
    delivery_load_by_team: deliveryLoadByTeam,
  };

  // ===== PEOPLE OPS =====
  const applications = peopleOps.filter(r => inPeriod(r.data.application_date));
  const offersAccepted = peopleOps.filter(r => inPeriod(r.data.offer_accepted_date));
  const newHires = peopleOps.filter(r => inPeriod(r.data.start_date));
  const exits = peopleOps.filter(r => inPeriod(r.data.exit_date));

  const activeHeadcount = peopleOps.filter(r => {
    const start = r.data.start_date ? new Date(r.data.start_date) : null;
    const exit = r.data.exit_date ? new Date(r.data.exit_date) : null;
    if (!start || start > rangeEnd) return false;
    if (exit && exit <= rangeEnd) return false;
    return true;
  }).length;

  const activeHeadcountAtStart = peopleOps.filter(r => {
    const start = r.data.start_date ? new Date(r.data.start_date) : null;
    const exit = r.data.exit_date ? new Date(r.data.exit_date) : null;
    if (!start || start >= rangeStart) return false;
    if (exit && exit < rangeStart) return false;
    return true;
  }).length;

  const attritionRate = activeHeadcountAtStart > 0 ? exits.length / activeHeadcountAtStart : null;

  const hiresWithBothDates = newHires.filter(r => r.data.application_date && r.data.start_date);
  const timeToHire = hiresWithBothDates.length > 0
    ? hiresWithBothDates.reduce((sum, r) => {
        const days = (new Date(r.data.start_date) - new Date(r.data.application_date)) / (1000 * 60 * 60 * 24);
        return sum + days;
      }, 0) / hiresWithBothDates.length
    : null;

  const offersWithBothDates = offersAccepted.filter(r => r.data.application_date && r.data.offer_accepted_date);
  const offerAcceptanceTime = offersWithBothDates.length > 0
    ? offersWithBothDates.reduce((sum, r) => {
        const days = (new Date(r.data.offer_accepted_date) - new Date(r.data.application_date)) / (1000 * 60 * 60 * 24);
        return sum + days;
      }, 0) / offersWithBothDates.length
    : null;

  const headcountByDept = {};
  for (const r of peopleOps) {
    const start = r.data.start_date ? new Date(r.data.start_date) : null;
    const exit = r.data.exit_date ? new Date(r.data.exit_date) : null;
    const isActiveAtEnd = start && start <= rangeEnd && (!exit || exit > rangeEnd);
    if (isActiveAtEnd) {
      const dept = r.data.department || 'Unassigned';
      headcountByDept[dept] = (headcountByDept[dept] || 0) + 1;
    }
  }

  const peopleOpsMetrics = {
    applications: applications.length,
    offers_accepted: offersAccepted.length,
    new_hires: newHires.length,
    exits: exits.length,
    active_headcount: activeHeadcount,
    time_to_hire_days: timeToHire,
    offer_acceptance_time_days: offerAcceptanceTime,
    attrition_rate: attritionRate,
    headcount_by_department: headcountByDept,
  };

  const hasAnyData =
    salesInPeriod.length > 0 ||
    activeProjects.length > 0 || completedInPeriod.length > 0 ||
    applications.length > 0 || newHires.length > 0;

  return {
    sales: salesMetrics,
    project_delivery: projectMetrics,
    people_ops: peopleOpsMetrics,
    monthlySpendConflicts,
    hasAnyData,
    // raw filtered sets, needed only for the CURRENT period's data quality summary
    salesInPeriod, activeProjects, completedInPeriod, applications, newHires,
  };
}

// --- Calculate both periods ---
const current = calculateMetrics(periodStart, periodEnd);
const previous = calculateMetrics(prevPeriodStart, prevPeriodEnd);

// ============================================
// No-data check — based on the CURRENT period only
// ============================================
if (!current.hasAnyData) {
  return [{
    json: {
      period_type: `custom_${period.start_date}_${period.end_date}_${Date.now()}`,
      start_date: period.start_date,
      end_date: period.end_date,
      no_data: true,
      metrics: null,
      previous_period: null,
      data_quality_summary: null,
      ai_executive_summary: null,
      ai_risks_anomalies: [],
      ai_recommended_actions: [],
      ai_data_quality_notes: null,
    }
  }];
}

// ============================================
// DATA QUALITY SUMMARY — current period only
// ============================================
const flagCounts = {};
for (const r of allRecords) {
  for (const flag of (r.quality_flags || [])) {
    flagCounts[flag] = (flagCounts[flag] || 0) + 1;
  }
}

const departmentsWithNoRecords = [];
if (current.salesInPeriod.length === 0) departmentsWithNoRecords.push('sales');
if (current.activeProjects.length === 0 && current.completedInPeriod.length === 0) departmentsWithNoRecords.push('project_delivery');
if (current.applications.length === 0 && current.newHires.length === 0) departmentsWithNoRecords.push('people_ops');

const dataQualitySummary = {
  flag_counts: {
    ...flagCounts,
    ...(current.monthlySpendConflicts.size > 0 ? { inconsistent_marketing_spend_in_month: current.monthlySpendConflicts.size } : {})
  },
  total_flagged_records: allRecords.filter(r => (r.quality_flags || []).length > 0).length,
  departments_with_no_records: departmentsWithNoRecords,
};

// ============================================
// FINAL OUTPUT — now includes previous_period
// ============================================
return [{
  json: {
    period_type: `custom_${period.start_date}_${period.end_date}_${Date.now()}`,
    start_date: period.start_date,
    end_date: period.end_date,
    no_data: false,
    metrics: {
      sales: current.sales,
      project_delivery: current.project_delivery,
      people_ops: current.people_ops,
    },
    previous_period: previous.hasAnyData ? {
      sales: previous.sales,
      project_delivery: previous.project_delivery,
      people_ops: previous.people_ops,
    } : null, // no prior data to compare against let Claude know honestly, not send zeros
    data_quality_summary: dataQualitySummary,
  }
}];

// Runs right before "Respond to Webhook".
// Input: the Supabase upsert node's response (array-wrapped row, with
// jsonb columns possibly returned as JSON-encoded strings).
// Output: one clean object, with every jsonb field as a real object/array.

const raw = items[0].json;
const row = Array.isArray(raw) ? raw[0] : raw;

if (!row) {
  return [{
    json: {
      error: true,
      message: 'No report row returned from Supabase upsert.',
    }
  }];
}

function parseIfString(val, fallback) {
  if (typeof val !== 'string') return val ?? fallback;
  try {
    return JSON.parse(val);
  } catch {
    return fallback;
  }
}

const cleaned = {
  id: row.id,
  period_type: row.period_type,
  start_date: row.start_date,
  end_date: row.end_date,
  metrics: parseIfString(row.metrics, null),
  data_quality_summary: parseIfString(row.data_quality_summary, null),
  ai_executive_summary: row.ai_executive_summary ?? null,
  ai_risks_anomalies: parseIfString(row.ai_risks_anomalies, []),
  ai_recommended_actions: parseIfString(row.ai_recommended_actions, []),
  ai_data_quality_notes: row.ai_data_quality_notes ?? null,
  review_status: row.review_status ?? null,
  generated_at: row.generated_at ?? null,
};

return [{ json: cleaned }];

